def skill(robot):
    if robot.is_holding():
        robot.put_aside()
    for _ in range(5):
        if robot.pick("blue cube"):
            if not robot.is_holding():
                continue
            if robot.place_on("tray"):
                return True
            if robot.is_holding():
                robot.put_aside()
        else:
            if robot.pick("red cube"):
                robot.put_aside()
            elif robot.pick("cube"):
                robot.put_aside()
    return False
